INSERT INTO match_player_prescriptions VALUES(2,36,'FC26','RCM','cm_holding','Defend',0.8070000000000000506,1,5,'모이세스 카이세도 — 85분 · 평점 8.2. RDM 슬롯(이 경기 lineup_pos)에 **이 경기 히트맵**을 대어 산출한 단일 경기 적합 0.896.','FotMob matchDetails 5739312 + SofaScore event 16285002; match_reports.id=2',unistr('HIGH 적합(단일 경기 실측 커널) / ⚠️ 단일 경기 프리셋이며 시즌 정본(prescriptions·team_tactic_setups)을 덮지 않는다. ⚠️ 이 경기 포메이션이 백3인데 슬롯 정본은 백4 기하다 — 슬롯 x가 완전히 대응하지 않는다.\u000a\u000a[2026-08-25 정정 — 존재하지 않는 슬롯으로 산출돼 있었다] 이 행의 pos_label은 원래 RDM였으나 **CHE 슬롯 정본에는 LDM·RDM이 존재하지 않는다** (CHE 3-4-2-1의 더블 피벗은 LCM 45 · RCM 55다). 역산 결과 옛 값 0.896은 **LDM 50 / RDM 61 기하**로 산출된 것이었고, 그 x는 어느 팀 slots에도 없는 값이다 (2026-08-24 transfer-watch 스킬이 「존재하지 않는 슬롯」으로 이미 적발한 그 표기다). 원인: 이 리포트는 2026-08-16에 작성됐는데 당시 CHE slots는 백4 기하뿐이었고(본문 7절이 「이 경기는 백3인데 slots 정본은 백4 기하다」로 명시한다), 이후 CHE 3-4-2-1 슬롯이 추가됐을 때 이 두 행이 이관되지 않았다. ⇒ 정본 슬롯 RCM(x=55, slot_type=CM)로 재산출했다: cm_holding/Defend **0.807**. ⚠️ 역할이 dm_dlp → cm_holding로 바뀐 것은 판단 변경이 아니라 **슬롯 유형이 DM이 아니라 CM이기 때문**이다 — CHE 3-4-2-1에 DM 슬롯 자체가 없다. ⚠️ 이 리포트 본문 표도 카이세도를 **RCM**으로 적고 있었고, 같은 3-4-2-1인 풀럼전(report 25)도 LCM·RCM을 쓴다 — 정정 방향이 원문·형제 리포트와 모두 일치한다.'),NULL,NULL);
