INSERT INTO match_player_prescriptions VALUES(20,43,'FC26','GK','gk_goalkeeper','Defend',0.974999999999999978,1,1,'GK 단일 경기 실측 적합 0.975 (hp 46).','SofaScore event 16846122 단일 경기 실측 → core.kernel.Kernel("FC26").best_fit_slot (regime 3 slots 기하). 슬롯 라벨은 /lineups players[] 배열 순서 파생(obs#97).','MATCH ONLY — 이 경기 재현 전용이며 시즌 prescriptions·slot_canon_roles를 덮지 않는다. ⚠️ 4-2-3-1의 RAM/LAM은 LIV slots 기하에 없어 **RM(x=85)/LM(x=14)** 로 산출했다 — 슬롯 x가 다르면 값이 달라진다(코사인은 x의 계단 함수). ⛔ hp<15인 4명(코우마스·니오니·무뇨스·라이트)은 **fit_sim NULL**이고 역할은 교대한 선수에게서 승계 표기했다 — 실측 근거가 아니라 자리 표시다. ⚠️ trail 국면 0분(리드 편향) · 친선 1경기 · Δ.02~.05는 EA 노이즈(obs#91).',NULL,NULL);
