INSERT INTO match_player_prescriptions VALUES(21,148,'FC26','GK','gk_goalkeeper','Defend',0.94299999999999995,1,0,'gk_goalkeeper/Defend 적합 0.940 — 정본과 일치하고 이 슬롯은 실측이 가장 안정적이다.','FotMob matchDetails+heatmap matchId=5868012 (26/27 라리가 R1) · 원문 reports/match-watch/2026-08-19-atm-malaga.md · docs/13-simeone-tactics.md','[2026-08-20] ⚠️ **원천 FotMob**(SofaScore 사이트 전역 403 대체 경로). 좌표 방위는 실증 검증(오블락 cx=13 ⇒ 자기 골문 cx=0 · 다니 cy=9.1 ↔ 마르틴 cy=55.0 ⇒ 낮은 cy=우측). ⛔ **PPDA 없음**(WhoScored 미접근) — 압박 관련 판단의 신뢰도가 낮다. ⚠️ **표본 1경기**이고 ATM 확장 첫 경기다.',NULL,NULL);
INSERT INTO match_player_prescriptions VALUES(21,149,'FC26','RB','fb_att_wb','Support',0.9170000000000000373,1,1,'⚠️ cb_wideback/Support 적합 0.321로 매우 낮다. 원인은 배정 슬롯 x=31과 실측 17.3의 Δ−14다. 역할 부적합이 아니라 **기하 불일치**일 가능성이 크다 — R2에서 재확인.','FotMob matchDetails+heatmap matchId=5868012 (26/27 라리가 R1) · 원문 reports/match-watch/2026-08-19-atm-malaga.md · docs/13-simeone-tactics.md','[2026-08-20] ⚠️ **원천 FotMob**(SofaScore 사이트 전역 403 대체 경로). 좌표 방위는 실증 검증(오블락 cx=13 ⇒ 자기 골문 cx=0 · 다니 cy=9.1 ↔ 마르틴 cy=55.0 ⇒ 낮은 cy=우측). ⛔ **PPDA 없음**(WhoScored 미접근) — 압박 관련 판단의 신뢰도가 낮다. ⚠️ **표본 1경기**이고 ATM 확장 첫 경기다.',NULL,NULL);
INSERT INTO match_player_prescriptions VALUES(21,150,'FC26','RCB','cb_bpd','Aggressive',0.8459999999999999743,1,2,'cb_bpd/Aggressive 0.737. 정본은 cb_defender/Balanced인데 실측 최적이 bpd로 나왔다 — ⚠️ 다만 실측 툴x 40.1이 슬롯 50과 Δ−10이라 이 차이가 기하에서 왔을 수 있다.','FotMob matchDetails+heatmap matchId=5868012 (26/27 라리가 R1) · 원문 reports/match-watch/2026-08-19-atm-malaga.md · docs/13-simeone-tactics.md','[2026-08-20] ⚠️ **원천 FotMob**(SofaScore 사이트 전역 403 대체 경로). 좌표 방위는 실증 검증(오블락 cx=13 ⇒ 자기 골문 cx=0 · 다니 cy=9.1 ↔ 마르틴 cy=55.0 ⇒ 낮은 cy=우측). ⛔ **PPDA 없음**(WhoScored 미접근) — 압박 관련 판단의 신뢰도가 낮다. ⚠️ **표본 1경기**이고 ATM 확장 첫 경기다.',NULL,NULL);
INSERT INTO match_player_prescriptions VALUES(21,151,'FC26','LCB','cb_bpd','Aggressive',0.8269999999999999574,1,3,'⭐ 정본(cb_stopper/Aggressive)과 갈린다 — 실측이 명백히 배급형이라 **cb_bpd/Build-Up**을 적용했다. 배정 슬롯 적합 0.797이고 실측 툴x 70.6이 슬롯 70과 Δ+0.6으로 **기하가 가장 정확한 슬롯**이다.','FotMob matchDetails+heatmap matchId=5868012 (26/27 라리가 R1) · 원문 reports/match-watch/2026-08-19-atm-malaga.md · docs/13-simeone-tactics.md','[2026-08-20] ⚠️ **원천 FotMob**(SofaScore 사이트 전역 403 대체 경로). 좌표 방위는 실증 검증(오블락 cx=13 ⇒ 자기 골문 cx=0 · 다니 cy=9.1 ↔ 마르틴 cy=55.0 ⇒ 낮은 cy=우측). ⛔ **PPDA 없음**(WhoScored 미접근) — 압박 관련 판단의 신뢰도가 낮다. ⚠️ **표본 1경기**이고 ATM 확장 첫 경기다.',NULL,NULL);
