INSERT INTO match_player_prescriptions VALUES(24,148,'FC26','GK','gk_goalkeeper','Defend',0.956999999999999962,1,0,'실측 툴x 50.6 ↔ GK 슬롯 50. 오픈플레이 실점 0·goals prevented +0.91로 이 경기 최고 수행.','SofaScore API event 16416302 (2026-08-23 라리가 R2) · 원문 reports/match-watch/2026-08-23-atm-villarreal.md · docs/13-simeone-tactics.md · 적합은 core.kernel.Kernel(''FC26'').best_fit_slot(regime 4)','⚠️ **표본 2경기** · **76~90분 10명 경기** · ⛔ **PPDA 미수집**(SofaScore 미제공 — R1의 7.77은 WhoScored/Opta 경로였다). ⚠️ 라인 52는 태클 26(상대 11)과 매체 서술(「팀이 매우 전진」·「트랜지션 취약」)로 추정한 값이고 **PPDA 없이 내린 판단**이라 R1보다 신뢰도가 낮다. ⚠️⚠️ 결과(2-2)와 내용(xG 0.78 대 3.60)의 괴리가 커 결과 기반 판단 금지.',NULL,NULL);
INSERT INTO match_player_prescriptions VALUES(24,166,'FC26','RB','fb_wingback','Balanced',0.8529999999999999805,1,1,'실측 툴x 81.1 ↔ RB 슬롯 86(Δ5). avg_y 18.9로 명백한 우측 — 「3-5-2」 서술을 반증하는 핵심 좌표다.','SofaScore API event 16416302 (2026-08-23 라리가 R2) · 원문 reports/match-watch/2026-08-23-atm-villarreal.md · docs/13-simeone-tactics.md · 적합은 core.kernel.Kernel(''FC26'').best_fit_slot(regime 4)','⚠️ **표본 2경기** · **76~90분 10명 경기** · ⛔ **PPDA 미수집**(SofaScore 미제공 — R1의 7.77은 WhoScored/Opta 경로였다). ⚠️ 라인 52는 태클 26(상대 11)과 매체 서술(「팀이 매우 전진」·「트랜지션 취약」)로 추정한 값이고 **PPDA 없이 내린 판단**이라 R1보다 신뢰도가 낮다. ⚠️⚠️ 결과(2-2)와 내용(xG 0.78 대 3.60)의 괴리가 커 결과 기반 판단 금지.',NULL,NULL);
