INSERT INTO match_player_prescriptions VALUES(24,167,'FC26','LB','fb_att_wb','Support',0.9180000000000000381,1,4,'실측 툴x 21.7 ↔ LB 슬롯 14(Δ8). **이 경기 최고 적합** — avg_x 54.8의 전진이 fb_att_wb와 정확히 맞는다. 사실상 좌측 윙백.','SofaScore API event 16416302 (2026-08-23 라리가 R2) · 원문 reports/match-watch/2026-08-23-atm-villarreal.md · docs/13-simeone-tactics.md · 적합은 core.kernel.Kernel(''FC26'').best_fit_slot(regime 4)','⚠️ **표본 2경기** · **76~90분 10명 경기** · ⛔ **PPDA 미수집**(SofaScore 미제공 — R1의 7.77은 WhoScored/Opta 경로였다). ⚠️ 라인 52는 태클 26(상대 11)과 매체 서술(「팀이 매우 전진」·「트랜지션 취약」)로 추정한 값이고 **PPDA 없이 내린 판단**이라 R1보다 신뢰도가 낮다. ⚠️⚠️ 결과(2-2)와 내용(xG 0.78 대 3.60)의 괴리가 커 결과 기반 판단 금지.',NULL,NULL);
INSERT INTO match_player_prescriptions VALUES(24,161,'FC26','RM','wm_winger','Attack',0.6770000000000000461,1,5,'⚠️⚠️ **슬롯 간 argmax를 쓰지 않았다.** RB 슬롯에서 .715로 더 높게 나왔으나 실측 툴x 73.1은 RM 슬롯 76에 근접(Δ3)하고 RB 86과는 Δ13이라 **기하 불일치**가 된다 — R1 푸빌 건에서 이미 경고된 실패 유형이다. RM .677을 그대로 기록한다.','SofaScore API event 16416302 (2026-08-23 라리가 R2) · 원문 reports/match-watch/2026-08-23-atm-villarreal.md · docs/13-simeone-tactics.md · 적합은 core.kernel.Kernel(''FC26'').best_fit_slot(regime 4)','⚠️ **표본 2경기** · **76~90분 10명 경기** · ⛔ **PPDA 미수집**(SofaScore 미제공 — R1의 7.77은 WhoScored/Opta 경로였다). ⚠️ 라인 52는 태클 26(상대 11)과 매체 서술(「팀이 매우 전진」·「트랜지션 취약」)로 추정한 값이고 **PPDA 없이 내린 판단**이라 R1보다 신뢰도가 낮다. ⚠️⚠️ 결과(2-2)와 내용(xG 0.78 대 3.60)의 괴리가 커 결과 기반 판단 금지.',NULL,NULL);
