INSERT INTO match_player_prescriptions VALUES(24,163,'FC26','CDM','dm_dlp','Roaming',0.8549999999999999823,1,7,'실측 툴x 45.1 ↔ CDM 슬롯 50(Δ5). 터치 82·패스 66·키패스 5 전부 팀 1위 — 실측이 배급형(dlp)을 강하게 지지한다. 선발 데뷔전.','SofaScore API event 16416302 (2026-08-23 라리가 R2) · 원문 reports/match-watch/2026-08-23-atm-villarreal.md · docs/13-simeone-tactics.md · 적합은 core.kernel.Kernel(''FC26'').best_fit_slot(regime 4)','⚠️ **표본 2경기** · **76~90분 10명 경기** · ⛔ **PPDA 미수집**(SofaScore 미제공 — R1의 7.77은 WhoScored/Opta 경로였다). ⚠️ 라인 52는 태클 26(상대 11)과 매체 서술(「팀이 매우 전진」·「트랜지션 취약」)로 추정한 값이고 **PPDA 없이 내린 판단**이라 R1보다 신뢰도가 낮다. ⚠️⚠️ 결과(2-2)와 내용(xG 0.78 대 3.60)의 괴리가 커 결과 기반 판단 금지.',NULL,NULL);
INSERT INTO match_player_prescriptions VALUES(24,154,'FC26','LCM','cm_b2b','Balanced',0.7459999999999999965,1,8,'실측 툴x 38.2 ↔ LCM 슬롯 36(Δ2). 배열순서상 LM이나 실측은 좌중앙이다 — 4-4-2 플랫 미드필드를 ATM 슬롯 어휘로 옮긴 결과.','SofaScore API event 16416302 (2026-08-23 라리가 R2) · 원문 reports/match-watch/2026-08-23-atm-villarreal.md · docs/13-simeone-tactics.md · 적합은 core.kernel.Kernel(''FC26'').best_fit_slot(regime 4)','⚠️ **표본 2경기** · **76~90분 10명 경기** · ⛔ **PPDA 미수집**(SofaScore 미제공 — R1의 7.77은 WhoScored/Opta 경로였다). ⚠️ 라인 52는 태클 26(상대 11)과 매체 서술(「팀이 매우 전진」·「트랜지션 취약」)로 추정한 값이고 **PPDA 없이 내린 판단**이라 R1보다 신뢰도가 낮다. ⚠️⚠️ 결과(2-2)와 내용(xG 0.78 대 3.60)의 괴리가 커 결과 기반 판단 금지.',NULL,NULL);
INSERT INTO match_player_prescriptions VALUES(24,158,'FC26','LM','wm_insidefwd','Attack',0.7510000000000000008,1,9,'실측 툴x 30.0 ↔ LM 슬롯 24(Δ6). ⚠️ 명목은 우측 포워드, 매체는 전원 「중앙 9번」인데 실측만 좌측이다 — **설계된 로테이션이 아니라 표류**로 판정했고 좌측 편류는 실측 단독 근거다.','SofaScore API event 16416302 (2026-08-23 라리가 R2) · 원문 reports/match-watch/2026-08-23-atm-villarreal.md · docs/13-simeone-tactics.md · 적합은 core.kernel.Kernel(''FC26'').best_fit_slot(regime 4)','⚠️ **표본 2경기** · **76~90분 10명 경기** · ⛔ **PPDA 미수집**(SofaScore 미제공 — R1의 7.77은 WhoScored/Opta 경로였다). ⚠️ 라인 52는 태클 26(상대 11)과 매체 서술(「팀이 매우 전진」·「트랜지션 취약」)로 추정한 값이고 **PPDA 없이 내린 판단**이라 R1보다 신뢰도가 낮다. ⚠️⚠️ 결과(2-2)와 내용(xG 0.78 대 3.60)의 괴리가 커 결과 기반 판단 금지.',NULL,NULL);
INSERT INTO match_player_prescriptions VALUES(24,162,'FC26','ST','st_false9','Build-Up',0.5729999999999999539,1,10,'실측 툴x 48.2 ↔ ST 슬롯 50(Δ2). ⚠️ 적합 .573이 낮은 것은 역할 부적합이 아니라 ⑴ ATM 슬롯 정본에 ST가 1자리인데 이 경기는 **투톱**이고 ⑵ 실측 중앙이 「전반 ST + 후반 RM」의 평균 혼합이기 때문이다.','SofaScore API event 16416302 (2026-08-23 라리가 R2) · 원문 reports/match-watch/2026-08-23-atm-villarreal.md · docs/13-simeone-tactics.md · 적합은 core.kernel.Kernel(''FC26'').best_fit_slot(regime 4)','⚠️ **표본 2경기** · **76~90분 10명 경기** · ⛔ **PPDA 미수집**(SofaScore 미제공 — R1의 7.77은 WhoScored/Opta 경로였다). ⚠️ 라인 52는 태클 26(상대 11)과 매체 서술(「팀이 매우 전진」·「트랜지션 취약」)로 추정한 값이고 **PPDA 없이 내린 판단**이라 R1보다 신뢰도가 낮다. ⚠️⚠️ 결과(2-2)와 내용(xG 0.78 대 3.60)의 괴리가 커 결과 기반 판단 금지.',NULL,NULL);
INSERT INTO match_player_prescriptions VALUES(24,160,'FC26','ST','st_false9','Build-Up',0.7489999999999999992,0,11,'실측 툴x 47.3 ↔ ST 슬롯 50(Δ2.7). ATM 슬롯 정본에 **CAM이 없어** 중앙 전진 미드필더를 ST로 받았다 — pos_class 자동값은 CAM이나 ATM 어휘에 부재한다(obs#310). ⭐ 45분 표본으로 **1도움**(85분 라인 사이 스루패스).','SofaScore API event 16416302 (2026-08-23 라리가 R2) · 원문 reports/match-watch/2026-08-23-atm-villarreal.md · 적합은 core.kernel.Kernel(''FC26'').best_fit_slot(regime 4)','⚠️ **교체 표본은 45분 미만이거나 경계값**이라 대표 히트맵·시즌 집계에서는 제외된다(스킬 §2). 여기 기록하는 적합은 **이 경기 한정 참고값**이다. ⚠️ 76~90분은 10명 경기다.',154,46);
INSERT INTO match_player_prescriptions VALUES(24,159,'FC26','RB','fb_att_wb','Support',0.8459999999999999743,0,12,'**푸빌(RB)의 교체**이고 실측 툴x 78.2가 푸빌의 81.1과 거의 같은 구역(Δ2.9)이다 ⇒ RB로 받는다. R1 처방도 RB였다. ⚠️ RM(76)이 기하상 더 가깝지만(Δ2.2 vs RB Δ7.8) **대체 관계와 R1 선례**를 우선했고, 적합도 RB가 더 높다(.846 vs .753).','SofaScore API event 16416302 (2026-08-23 라리가 R2) · 원문 reports/match-watch/2026-08-23-atm-villarreal.md · 적합은 core.kernel.Kernel(''FC26'').best_fit_slot(regime 4)','⚠️ **교체 표본은 45분 미만이거나 경계값**이라 대표 히트맵·시즌 집계에서는 제외된다(스킬 §2). 여기 기록하는 적합은 **이 경기 한정 참고값**이다. ⚠️ 76~90분은 10명 경기다.',166,66);
INSERT INTO match_player_prescriptions VALUES(24,155,'FC26','RM','wm_widemid','Build-Up',0.7199999999999999734,0,13,'실측 툴x 75.1 ↔ RM 슬롯 76(Δ0.9) — 기하 최근접. ⚠️ RCM(64)이 적합은 더 높지만(.822) Δ11.1의 **기하 불일치**라 채택하지 않았다(줄리아노 건과 같은 규칙). ⭐ 요렌테 78.2 > 바리오스 75.1로 **두 교체의 좌우 순서가 RB/RM으로 일관**된다.','SofaScore API event 16416302 (2026-08-23 라리가 R2) · 원문 reports/match-watch/2026-08-23-atm-villarreal.md · 적합은 core.kernel.Kernel(''FC26'').best_fit_slot(regime 4)','⚠️ **교체 표본은 45분 미만이거나 경계값**이라 대표 히트맵·시즌 집계에서는 제외된다(스킬 §2). 여기 기록하는 적합은 **이 경기 한정 참고값**이다. ⚠️ 76~90분은 10명 경기다.',162,66);
INSERT INTO match_player_prescriptions VALUES(24,172,'FC26','ST','st_false9','Build-Up',0.6939999999999999503,0,14,'실측 툴x 52.1 ↔ ST 슬롯 50(Δ2.1). ⛔⛔ **hit_points 13 < 15로 히트맵 기준 미달** — 이 적합값은 **표본 부족 상태의 참고값이고 처방 근거로 쓰면 안 된다**. 24분·터치 12로 「박스 밖에 머물렀다」는 서술과 정합.','SofaScore API event 16416302 (2026-08-23 라리가 R2) · 원문 reports/match-watch/2026-08-23-atm-villarreal.md · 적합은 core.kernel.Kernel(''FC26'').best_fit_slot(regime 4)','⚠️ **교체 표본은 45분 미만이거나 경계값**이라 대표 히트맵·시즌 집계에서는 제외된다(스킬 §2). 여기 기록하는 적합은 **이 경기 한정 참고값**이다. ⚠️ 76~90분은 10명 경기다.',156,66);
INSERT INTO match_player_prescriptions VALUES(24,165,'FC26','RCB','cb_bpd','Aggressive',0.7980000000000000426,0,15,'**76분 르노르망 퇴장 뒤 백4 복구용 투입**(루크만을 빼고 CB를 넣어 전방 1명 체제로 내려앉았다). 실측 툴x 69.3 ↔ RCB 슬롯 65(Δ4.3). ⚠️ RB(86)가 적합은 높지만(.840) Δ16.7의 기하 불일치라 채택하지 않았다.','SofaScore API event 16416302 (2026-08-23 라리가 R2) · 원문 reports/match-watch/2026-08-23-atm-villarreal.md · 적합은 core.kernel.Kernel(''FC26'').best_fit_slot(regime 4)','⚠️ **교체 표본은 45분 미만이거나 경계값**이라 대표 히트맵·시즌 집계에서는 제외된다(스킬 §2). 여기 기록하는 적합은 **이 경기 한정 참고값**이다. ⚠️ 76~90분은 10명 경기다.',158,79);
INSERT INTO match_player_prescriptions VALUES(22,17,'FC26','LCB','cb_wideback','Defend',0.4349999999999999978,0,11,'74'' 파우 토레스 대체로 LCB 투입(백라인 안정화). ⛔⛔ **hit_points 1 — 그리드가 셀 1개뿐**이라 `map25`가 사실상 단일 점이다. fit 0.435는 **hp 1의 산물로 무의미**하고, 평균위치 툴x 5.0도 LCB 슬롯 37과 Δ32라 기하가 성립하지 않는다. **판정 유보** — 값은 결손 대신 기록만 한다.','FotMob matchDetails matchId=5795369 + WhoScored matchCentreData(Opta) matchId=1983554 · 원문 reports/match-watch/2026-08-23-avl-brighton.md · 적합은 core.kernel.Kernel(''FC26'').best_fit_slot(regime 1)','⛔⛔ **표본 극소 — 이 fit은 참고값이고 처방 근거가 아니다.** 대표 히트맵·시즌 집계 기준은 **45분+ · hit_points 15+**인데 이 행은 두 조건 모두 미달이다. `prescriptions`·`slot_canon_roles`로 승격 금지. ⚠️ 이 경기는 **40분 주앙 고메스 퇴장으로 50분간 10명**이었다 — 교체 국면 전체가 10명 구조다.',4,74);
INSERT INTO match_player_prescriptions VALUES(22,11,'FC26','LM','wm_widemid','Build-Up',0.8299999999999999601,0,12,'74'' 바클리 대체 투입인데 **좌측으로 배치됐다**(ay 82.5 · 툴x 17.5 ↔ LM 슬롯 14, Δ3.5) — 10명 상태의 재배치다. ⛔ **hit_points 4**라 0.830은 수치가 높아 보여도 **참고 불가**다.','FotMob matchDetails matchId=5795369 + WhoScored matchCentreData(Opta) matchId=1983554 · 원문 reports/match-watch/2026-08-23-avl-brighton.md · 적합은 core.kernel.Kernel(''FC26'').best_fit_slot(regime 1)','⛔⛔ **표본 극소 — 이 fit은 참고값이고 처방 근거가 아니다.** 대표 히트맵·시즌 집계 기준은 **45분+ · hit_points 15+**인데 이 행은 두 조건 모두 미달이다. `prescriptions`·`slot_canon_roles`로 승격 금지. ⚠️ 이 경기는 **40분 주앙 고메스 퇴장으로 50분간 10명**이었다 — 교체 국면 전체가 10명 구조다.',21,74);
INSERT INTO match_player_prescriptions VALUES(22,78,'FC26','LB','fb_att_wb','Support',0.7960000000000000408,0,13,'81'' 마첸 대체. 툴x 7.4 ↔ LB 슬롯 13(Δ5.6)로 기하는 맞는다. ⛔ **hit_points 3**이라 참고값.','FotMob matchDetails matchId=5795369 + WhoScored matchCentreData(Opta) matchId=1983554 · 원문 reports/match-watch/2026-08-23-avl-brighton.md · 적합은 core.kernel.Kernel(''FC26'').best_fit_slot(regime 1)','⛔⛔ **표본 극소 — 이 fit은 참고값이고 처방 근거가 아니다.** 대표 히트맵·시즌 집계 기준은 **45분+ · hit_points 15+**인데 이 행은 두 조건 모두 미달이다. `prescriptions`·`slot_canon_roles`로 승격 금지. ⚠️ 이 경기는 **40분 주앙 고메스 퇴장으로 50분간 10명**이었다 — 교체 국면 전체가 10명 구조다.',6,81);
INSERT INTO match_player_prescriptions VALUES(22,59,'FC26','RM','wm_widemid','Defend',0.6770000000000000461,0,14,'82'' 맥긴 대체로 우측 투입. 툴x 83.3 ↔ RM 슬롯 85(Δ1.7)로 기하는 정확하다. 포커스가 **Defend**로 나온 것은 8분간 수비 가담만 했기 때문이다(태클 1·클리어 1, 공격 기여 0). ⛔ hp 4 — 참고값.','FotMob matchDetails matchId=5795369 + WhoScored matchCentreData(Opta) matchId=1983554 · 원문 reports/match-watch/2026-08-23-avl-brighton.md · 적합은 core.kernel.Kernel(''FC26'').best_fit_slot(regime 1)','⛔⛔ **표본 극소 — 이 fit은 참고값이고 처방 근거가 아니다.** 대표 히트맵·시즌 집계 기준은 **45분+ · hit_points 15+**인데 이 행은 두 조건 모두 미달이다. `prescriptions`·`slot_canon_roles`로 승격 금지. ⚠️ 이 경기는 **40분 주앙 고메스 퇴장으로 50분간 10명**이었다 — 교체 국면 전체가 10명 구조다.',10,82);
INSERT INTO match_player_prescriptions VALUES(22,58,'FC26','LM','wm_winger','Attack',NULL,0,15,'86'' 부엔디아 대체 · **빌라 데뷔전**. ⛔⛔⛔ **4분 · 터치 0 · hit_points 0 · cells/map25 NULL** — 히트맵이 아예 없어 **이 경기의 적합을 산출할 수 없다**. `fit_sim`을 **NULL로 둔다**(0이 아니다 — 결손이다). 역할 `wm_winger/Attack`은 이 경기 실측이 아니라 **시즌 정본값**(transfer_targets LM, 38경기, .771)을 자리 표시로 옮겨 적은 것이다 — **이 경기의 근거가 아님을 명기한다.** 기록 가치는 **데뷔 사실**뿐이다.','FotMob matchDetails matchId=5795369 + WhoScored matchCentreData(Opta) matchId=1983554 · 원문 reports/match-watch/2026-08-23-avl-brighton.md · 적합은 core.kernel.Kernel(''FC26'').best_fit_slot(regime 1)','⛔⛔ **표본 극소 — 이 fit은 참고값이고 처방 근거가 아니다.** 대표 히트맵·시즌 집계 기준은 **45분+ · hit_points 15+**인데 이 행은 두 조건 모두 미달이다. `prescriptions`·`slot_canon_roles`로 승격 금지. ⛔⛔⛔ **이 행의 `fit_sim`은 NULL이다 — 값이 낮은 게 아니라 산출 자체가 불가능하다.**',14,86);
INSERT INTO match_player_prescriptions VALUES(23,50,'FC26','CAM','cam_playmaker','Build-Up',0.6580000000000000293,0,11,'63'' 투입. 툴x 56.2 ↔ CAM 슬롯 47(Δ9.2). ⭐ **hit_points 18로 그리드 기준은 통과**했고 분(27)만 미달이라 AVL 교체들보다 신뢰도가 높다. ⚠️ **대체 선수를 특정하지 못했다** — 리포트가 「63분 무뇨스와 맥알리스터 투입」으로만 적고 누구와 교체됐는지 쓰지 않아 `replaced_player_id`를 **NULL로 둔다**(추정 금지).','FotMob matchDetails matchId=5795371 · 원문 reports/match-watch/2026-08-23-liv-newcastle.md · 적합은 core.kernel.Kernel(''FC26'').best_fit_slot(regime 3)','⛔⛔ **표본 극소 — 이 fit은 참고값이고 처방 근거가 아니다.** 대표 히트맵·시즌 집계 기준은 **45분+ · hit_points 15+**인데 이 행은 **분(27) 미달이나 hit_points 18은 통과**다. `prescriptions`·`slot_canon_roles`로 승격 금지. / [2026-08-24 D+2] ⭐ **`replaced_player_id` 결손 해소 — 맥알리스터는 63분 비르츠(pid=52)를 대체했다.** D+1까지는 리포트가 「63분 무뇨스와 맥알리스터 투입」으로만 적어 상대를 특정하지 못했고 추정을 금지해 NULL로 두었다. 출처: FotMob matchDetails(matchId=5795371) `events.Substitution` — 63분 AWAY 2건이 **Mac Allister ← Wirtz** · **Muñoz ← Ngumoha**로 분리 기록돼 있다. ⇒ 맥알리스터 툴x 56.2가 CAM 슬롯 47과 Δ9.2로 벌어진 것은 **비르츠의 CAM 자리를 그대로 물려받되 더 깊게 섰다**는 뜻이다.',52,63);
INSERT INTO match_player_prescriptions VALUES(23,88,'FC26','RM','wm_winger','Attack',0.7790000000000000257,0,12,'63'' 응구모하 대체로 우측 투입. 툴x 82.4 ↔ RM 슬롯 77(Δ5.4). ⭐ **hit_points 17로 그리드 기준 통과** · 적합 0.779는 응구모하의 이 경기 수행(터치 21·박스 안 1)과 대비된다 — obs#308의 「RM 선발 경쟁 즉시 개시」 근거와 정합. ⚠️ 단 27분 표본이고, 스페인어권은 「apenas había intervenido」로 반대 평가를 냈다(D+1 충돌 미해소).','FotMob matchDetails matchId=5795371 · 원문 reports/match-watch/2026-08-23-liv-newcastle.md · 적합은 core.kernel.Kernel(''FC26'').best_fit_slot(regime 3)','⛔⛔ **표본 극소 — 이 fit은 참고값이고 처방 근거가 아니다.** 대표 히트맵·시즌 집계 기준은 **45분+ · hit_points 15+**인데 이 행은 **분(27) 미달이나 hit_points 17은 통과**다. `prescriptions`·`slot_canon_roles`로 승격 금지.',114,63);
INSERT INTO match_player_prescriptions VALUES(23,85,'FC26','RCB','cb_bpd','Aggressive',0.7279999999999999805,0,13,'70'' 자케 대체. 툴x 71.3 ↔ RCB 슬롯 68(Δ3.3). ⭐ **hit_points 35로 그리드 기준을 여유 있게 통과** — 이 4명 중 표본이 가장 낫다. 20분 표본이라 분 기준만 미달이다.','FotMob matchDetails matchId=5795371 · 원문 reports/match-watch/2026-08-23-liv-newcastle.md · 적합은 core.kernel.Kernel(''FC26'').best_fit_slot(regime 3)','⛔⛔ **표본 극소 — 이 fit은 참고값이고 처방 근거가 아니다.** 대표 히트맵·시즌 집계 기준은 **45분+ · hit_points 15+**인데 이 행은 **분(20) 미달이나 hit_points 35는 여유 있게 통과**다. `prescriptions`·`slot_canon_roles`로 승격 금지.',89,70);
INSERT INTO match_player_prescriptions VALUES(23,71,'FC26','CAM','cam_halfwinger','Balanced',0.5859999999999999654,0,14,'78'' **흐라벤베르흐(LDM) 대체**로 투입됐고 그래서 `pos_class`가 LDM으로 적재됐지만, ⭐ **실측 그리드는 전부 공격 3분의 1에 있다**(`map25=05050X0005000000000000000`, avg_x 76.1). 리포트도 「막판 공격 숫자를 담당」으로 적는다. ⛔ **LDM 슬롯으로 계산하면 fit이 진짜 0.000이 나온다** — 인공물이 아니라 DM 커널과 겹치는 영역이 **0**이기 때문이다. ⇒ 실측 우선 원칙에 따라 **CAM(툴x 41.7 ↔ 슬롯 47, Δ5.3) 기준 0.586**을 기록한다. ⛔ hp 5라 어디까지나 참고값이다.','FotMob matchDetails matchId=5795371 · 원문 reports/match-watch/2026-08-23-liv-newcastle.md · 적합은 core.kernel.Kernel(''FC26'').best_fit_slot(regime 3)','⛔⛔ **표본 극소 — 이 fit은 참고값이고 처방 근거가 아니다.** 대표 히트맵·시즌 집계 기준은 **45분+ · hit_points 15+**인데 이 행은 두 조건 모두 미달이다. `prescriptions`·`slot_canon_roles`로 승격 금지. ⚠️ **슬롯을 pos_class(LDM)가 아니라 실측 그리드로 정했다** — 아래 사유 참조.',49,78);
INSERT INTO match_player_prescriptions VALUES(25,31,'FC26','GK','gk_goalkeeper','Balanced',0.960999999999999966,1,1,'3-4-2-1 GK 슬롯 정본 x=50; Opta 단일 경기 map25·hp38 커널 argmax.; [08-26 영상 반영, obs#348] 유지 — 로빈슨 로빙 위기에서 전진을 주저(축수저) ⇒ gk_sweeper 아님이 실증. 혹평(4중 정합)은 역할 선택과 무관.','FotMob matchDetails matchId=5795372 (curl, 2026-08-25) — 라인업·득점·교체·팀/선수 스탯·xG·물리량 / WhoScored matchCentreData(Opta) matchId=1983550 이벤트 1659건 — 터치 좌표·5x5 그리드·PPDA / Chelsea FC 공식 리포트 · Guardian(Jonathan Wilson) · Sky Sports · El País · Cadena SER · AS (2026-08-24~25). / 리포트: reports/match-watch/2026-08-24-che-fulham.md · Guardian 분석 https://www.theguardian.com/football/2026/aug/24/premier-league-chelsea-xabi-alonso-fulham','measured(match-only). 단일 경기 fit; 시즌 처방 승격 금지.',NULL,NULL);
