INSERT INTO match_player_prescriptions VALUES(26,1,'FC26','GK','gk_goalkeeper','Defend',0.960999999999999966,1,0,'이 경기 전용. 슬롯은 SofaScore lineups 행 + 좌우 tool_x 순서로 배정했고 커널 best_fit_slot으로 단일 경기 fit을 산출했다. GK Defend .961. 42% 패스 정확도는 부정확이 아니라 설계된 롱 분배로 읽어야 한다','SofaScore event 16363249(lineups·average-positions·heatmap·statistics·incidents) + FotMob matchDetails 5795427(xG 4종 동일 스냅샷) + 알론소/휘르첼러 기자회견 1차 + Trivela(브라질, 2026-08-30) + 첼시 공식 매치리포트 + CBS James Benge(08-28·08-30)','측정 + 1차 소스. ⚠️PPDA 미수집. ⚠️제공사 편차: 점유 25.6%(Opta)↔26%, xG 2.97(Opta/SofaScore)↔2.93(FotMob 채택), 패스 성공146(Opta)↔시도227(FotMob). ⚠️단일 경기 fit이 26% 점유로 전 포지션 하향 왜곡됐다 — 시즌 역할 근거로 쓰면 안 된다. ⚠️영상 미수행(경기 전용 전술 분석 영상 부재 + 유튜브 메타데이터 취득 실패) — §2-1a D+1~D+3에서 재시도.',NULL,NULL);
