INSERT INTO match_player_prescriptions VALUES(29,148,'FC26','GK','gk_goalkeeper','Defend',0.982999999999999985,1,0,'이 경기 전용. 슬롯은 SofaScore lineups 행 + 좌우 tool_x 순서로 배정했고 커널 best_fit_slot으로 단일 경기 fit을 산출했다. gk_goalkeeper/Defend .983','SofaScore event 16416316 + FotMob matchDetails 5868040(xG 4종 동일 스냅샷) + 시메오네/루이스 가르시아 플라사 기자회견 1차 + 바에나 본인 발언 + El Desmarque·VAVEL·Into the Calderón 우노포르우노 3건 + 101TV(세비야 지역, 상대 관점) + 덴마크어(율만-바리오스 역할 분담 인과) + 슬로바키아어(4-4-2 명시)','측정 + 1차 소스. ⛔PPDA 미수집(ATM 3회차 연속) — 「전환 중심」 주장의 정량 검증 불가. ⛔전술 분석 영상 0건(하이라이트만, 어떤 영상도 시청하지 않았고 리포트에 영상 근거 문장 없음). ⚠️event_id 출처 혼재: ATM 시리즈는 08-19 말라가전이 FotMob(5868012), 08-23·08-29가 SofaScore다. ⚠️바에나 ST fit .499는 부적합이 아니라 역할 정의다 — 다른 슬롯 fit은 LCM .771·RCM .685·LM .583으로 커널이 읽은 실체는 「중앙 미드필더 높이에서 뛰는 공격수」다. ⚠️포메이션 충돌: 실측·슬로바키아·한국·ED 프리뷰 4-4-2 ↔ Infobae/EFE 4-2-3-1 — 실측 채택, Infobae 계열이 R2에 이어 2회 연속 다르게 적는다. ⚠️82분 세비야 PK 클레임은 incidents에 PK 판정이 없어 채택하지 않았다. ⚠️서브에이전트가 보고한 「R2 리포트 바에나 이적료 오기」는 파일 grep 결과 해당 문구가 없어 기각했다. ⛔Marca·AS·Relevo 크롤러 차단.',NULL,NULL);
INSERT INTO match_player_prescriptions VALUES(29,167,'FC26','LB','fb_fullback','Balanced',0.7890000000000000346,1,1,'이 경기 전용. 슬롯은 SofaScore lineups 행 + 좌우 tool_x 순서로 배정했고 커널 best_fit_slot으로 단일 경기 fit을 산출했다. fb_fullback/Balanced .789. ⚠️3개 매체(5·5·6)가 실측 6.5보다 가혹 — 미겔 시에라 골에서 예리하지 못했다','SofaScore event 16416316 + FotMob matchDetails 5868040(xG 4종 동일 스냅샷) + 시메오네/루이스 가르시아 플라사 기자회견 1차 + 바에나 본인 발언 + El Desmarque·VAVEL·Into the Calderón 우노포르우노 3건 + 101TV(세비야 지역, 상대 관점) + 덴마크어(율만-바리오스 역할 분담 인과) + 슬로바키아어(4-4-2 명시)','측정 + 1차 소스. ⛔PPDA 미수집(ATM 3회차 연속) — 「전환 중심」 주장의 정량 검증 불가. ⛔전술 분석 영상 0건(하이라이트만, 어떤 영상도 시청하지 않았고 리포트에 영상 근거 문장 없음). ⚠️event_id 출처 혼재: ATM 시리즈는 08-19 말라가전이 FotMob(5868012), 08-23·08-29가 SofaScore다. ⚠️바에나 ST fit .499는 부적합이 아니라 역할 정의다 — 다른 슬롯 fit은 LCM .771·RCM .685·LM .583으로 커널이 읽은 실체는 「중앙 미드필더 높이에서 뛰는 공격수」다. ⚠️포메이션 충돌: 실측·슬로바키아·한국·ED 프리뷰 4-4-2 ↔ Infobae/EFE 4-2-3-1 — 실측 채택, Infobae 계열이 R2에 이어 2회 연속 다르게 적는다. ⚠️82분 세비야 PK 클레임은 incidents에 PK 판정이 없어 채택하지 않았다. ⚠️서브에이전트가 보고한 「R2 리포트 바에나 이적료 오기」는 파일 grep 결과 해당 문구가 없어 기각했다. ⛔Marca·AS·Relevo 크롤러 차단.',NULL,NULL);
