INSERT INTO match_player_prescriptions VALUES(28,70,'FC26','LB','fb_att_wb','Support',0.9207999999999999519,0,11,'교체 투입(71′, Miloš Kerkez 대체). 표본 19분·히트포인트 21로 **45분 미만이라 시즌 집계에서 제외**했고, 아래 fit은 이 경기 전용 참고값이다. 슬롯은 incidents의 교체 짝과 투입 후 평균 위치로 배정했다.','SofaScore event 16363254 + FotMob matchDetails 5795431(xG 4종 동일 스냅샷) + 이라올라/글라스너 기자회견 1차(liverpoolfc.com 전문·Sky) + premierleague.com Alex Keble(2026-06-04) + transferhub 패스 네트워크(2026-08-30) + Eurosport.de/kicker(비르츠 역할 정본) + 헝가리어 nb1.hu·feol.hu(쇼보슬러이 RB 전환)','측정 + 1차 소스. ⛔PPDA 미수집(3회차 연속) — 프록시로 전반 집단 주행 −3km만 확보. ⚠️xG 제공사 편차: 1.75(FotMob 채택) ↔ 1.61(Opta/Sky). ⚠️비르츠 실측 6.4 ↔ ESPN 7·BBC 7·kicker·Sky DE 긍정(어시 1 + 취소골 1 + 유효 헤더 1) — 충돌 기록, 실측 채택하되 산출사 아티팩트 의심. ⚠️자케 8.2는 패스 94회 볼륨 주도값이고 라인 관리 실책 지적이 병존한다. ⚠️쇼보슬러이 fit .567은 71분 이후 RB 전환으로 통합 그리드가 두 역할 평균이 된 결과다 — 「부적합」으로 읽으면 안 된다. ⛔소스 폐기: tacticalfootballanalysis.com이 본머스 승점·순위를 2개 동시에 틀렸다. ⚠️영상 미수행.',47,71);
INSERT INTO match_player_prescriptions VALUES(28,114,'FC26','RM','wm_winger','Attack',0.4667000000000000037,0,12,'교체 투입(71′, Cody Gakpo 대체). 표본 19분·히트포인트 19로 **45분 미만이라 시즌 집계에서 제외**했고, 아래 fit은 이 경기 전용 참고값이다. 슬롯은 incidents의 교체 짝과 투입 후 평균 위치로 배정했다.','SofaScore event 16363254 + FotMob matchDetails 5795431(xG 4종 동일 스냅샷) + 이라올라/글라스너 기자회견 1차(liverpoolfc.com 전문·Sky) + premierleague.com Alex Keble(2026-06-04) + transferhub 패스 네트워크(2026-08-30) + Eurosport.de/kicker(비르츠 역할 정본) + 헝가리어 nb1.hu·feol.hu(쇼보슬러이 RB 전환)','측정 + 1차 소스. ⛔PPDA 미수집(3회차 연속) — 프록시로 전반 집단 주행 −3km만 확보. ⚠️xG 제공사 편차: 1.75(FotMob 채택) ↔ 1.61(Opta/Sky). ⚠️비르츠 실측 6.4 ↔ ESPN 7·BBC 7·kicker·Sky DE 긍정(어시 1 + 취소골 1 + 유효 헤더 1) — 충돌 기록, 실측 채택하되 산출사 아티팩트 의심. ⚠️자케 8.2는 패스 94회 볼륨 주도값이고 라인 관리 실책 지적이 병존한다. ⚠️쇼보슬러이 fit .567은 71분 이후 RB 전환으로 통합 그리드가 두 역할 평균이 된 결과다 — 「부적합」으로 읽으면 안 된다. ⛔소스 폐기: tacticalfootballanalysis.com이 본머스 승점·순위를 2개 동시에 틀렸다. ⚠️영상 미수행.',53,71);
