INSERT INTO match_player_prescriptions VALUES(29,165,'FC26','RCB','cb_bpd','Build-Up',0.8141000000000000458,0,11,'교체 투입(66′, Marcos Llorente 대체). 표본 24분·히트포인트 19로 **45분 미만이라 시즌 집계에서 제외**했고, 아래 fit은 이 경기 전용 참고값이다. 슬롯은 incidents의 교체 짝과 투입 후 평균 위치로 배정했다.','SofaScore event 16416316 + FotMob matchDetails 5868040(xG 4종 동일 스냅샷) + 시메오네/루이스 가르시아 플라사 기자회견 1차 + 바에나 본인 발언 + El Desmarque·VAVEL·Into the Calderón 우노포르우노 3건 + 101TV(세비야 지역, 상대 관점) + 덴마크어(율만-바리오스 역할 분담 인과) + 슬로바키아어(4-4-2 명시)','측정 + 1차 소스. ⛔PPDA 미수집(ATM 3회차 연속) — 「전환 중심」 주장의 정량 검증 불가. ⛔전술 분석 영상 0건(하이라이트만, 어떤 영상도 시청하지 않았고 리포트에 영상 근거 문장 없음). ⚠️event_id 출처 혼재: ATM 시리즈는 08-19 말라가전이 FotMob(5868012), 08-23·08-29가 SofaScore다. ⚠️바에나 ST fit .499는 부적합이 아니라 역할 정의다 — 다른 슬롯 fit은 LCM .771·RCM .685·LM .583으로 커널이 읽은 실체는 「중앙 미드필더 높이에서 뛰는 공격수」다. ⚠️포메이션 충돌: 실측·슬로바키아·한국·ED 프리뷰 4-4-2 ↔ Infobae/EFE 4-2-3-1 — 실측 채택, Infobae 계열이 R2에 이어 2회 연속 다르게 적는다. ⚠️82분 세비야 PK 클레임은 incidents에 PK 판정이 없어 채택하지 않았다. ⚠️서브에이전트가 보고한 「R2 리포트 바에나 이적료 오기」는 파일 grep 결과 해당 문구가 없어 기각했다. ⛔Marca·AS·Relevo 크롤러 차단.',159,66);
INSERT INTO match_player_prescriptions VALUES(29,157,'FC26','ST','cm_b2b','Balanced',NULL,0,12,'교체 투입(66′, Ademola Lookman 대체). 표본 24분·히트포인트 12로 **히트포인트 15 미만이라 그리드가 무효**다 — fit은 산출하지 않았고 슬롯만 기록한다. 슬롯은 incidents의 교체 짝과 투입 후 평균 위치로 배정했다.','SofaScore event 16416316 + FotMob matchDetails 5868040(xG 4종 동일 스냅샷) + 시메오네/루이스 가르시아 플라사 기자회견 1차 + 바에나 본인 발언 + El Desmarque·VAVEL·Into the Calderón 우노포르우노 3건 + 101TV(세비야 지역, 상대 관점) + 덴마크어(율만-바리오스 역할 분담 인과) + 슬로바키아어(4-4-2 명시)','측정 + 1차 소스. ⛔PPDA 미수집(ATM 3회차 연속) — 「전환 중심」 주장의 정량 검증 불가. ⛔전술 분석 영상 0건(하이라이트만, 어떤 영상도 시청하지 않았고 리포트에 영상 근거 문장 없음). ⚠️event_id 출처 혼재: ATM 시리즈는 08-19 말라가전이 FotMob(5868012), 08-23·08-29가 SofaScore다. ⚠️바에나 ST fit .499는 부적합이 아니라 역할 정의다 — 다른 슬롯 fit은 LCM .771·RCM .685·LM .583으로 커널이 읽은 실체는 「중앙 미드필더 높이에서 뛰는 공격수」다. ⚠️포메이션 충돌: 실측·슬로바키아·한국·ED 프리뷰 4-4-2 ↔ Infobae/EFE 4-2-3-1 — 실측 채택, Infobae 계열이 R2에 이어 2회 연속 다르게 적는다. ⚠️82분 세비야 PK 클레임은 incidents에 PK 판정이 없어 채택하지 않았다. ⚠️서브에이전트가 보고한 「R2 리포트 바에나 이적료 오기」는 파일 grep 결과 해당 문구가 없어 기각했다. ⛔Marca·AS·Relevo 크롤러 차단.',158,66);
INSERT INTO match_player_prescriptions VALUES(29,156,'FC26','RCM','cm_b2b','Balanced',NULL,0,13,'교체 투입(72′, Kang-In Lee 대체). 표본 18분·히트포인트 6로 **히트포인트 15 미만이라 그리드가 무효**다 — fit은 산출하지 않았고 슬롯만 기록한다. 슬롯은 incidents의 교체 짝과 투입 후 평균 위치로 배정했다.','SofaScore event 16416316 + FotMob matchDetails 5868040(xG 4종 동일 스냅샷) + 시메오네/루이스 가르시아 플라사 기자회견 1차 + 바에나 본인 발언 + El Desmarque·VAVEL·Into the Calderón 우노포르우노 3건 + 101TV(세비야 지역, 상대 관점) + 덴마크어(율만-바리오스 역할 분담 인과) + 슬로바키아어(4-4-2 명시)','측정 + 1차 소스. ⛔PPDA 미수집(ATM 3회차 연속) — 「전환 중심」 주장의 정량 검증 불가. ⛔전술 분석 영상 0건(하이라이트만, 어떤 영상도 시청하지 않았고 리포트에 영상 근거 문장 없음). ⚠️event_id 출처 혼재: ATM 시리즈는 08-19 말라가전이 FotMob(5868012), 08-23·08-29가 SofaScore다. ⚠️바에나 ST fit .499는 부적합이 아니라 역할 정의다 — 다른 슬롯 fit은 LCM .771·RCM .685·LM .583으로 커널이 읽은 실체는 「중앙 미드필더 높이에서 뛰는 공격수」다. ⚠️포메이션 충돌: 실측·슬로바키아·한국·ED 프리뷰 4-4-2 ↔ Infobae/EFE 4-2-3-1 — 실측 채택, Infobae 계열이 R2에 이어 2회 연속 다르게 적는다. ⚠️82분 세비야 PK 클레임은 incidents에 PK 판정이 없어 채택하지 않았다. ⚠️서브에이전트가 보고한 「R2 리포트 바에나 이적료 오기」는 파일 grep 결과 해당 문구가 없어 기각했다. ⛔Marca·AS·Relevo 크롤러 차단.',162,72);
