INSERT INTO match_player_prescriptions VALUES(2,76,'FC26','ST','st_false9','Build-Up',0.5540000000000000479,0,99,'잭슨 — 58분 웰벡과 교체 투입, 32분 · 평점 7.2. 원문 평가는 「직선 러닝으로 찬스, 골대 강타」다. ST 슬롯(CHE 정본 x=42)에 **이 경기 히트맵**(hit_points 16)을 대어 산출한 단일 경기 적합 **0.554 / st_false9 · Build-Up**. ⚠️ 시즌 정본(AVL 26/27 st_false9·**Attack** 0.724, 28경기)과 **포커스가 갈린다** — 32분 표본에서 하강 수령 비중이 커 Build-Up이 선택됐다. obs#348 원칙(개별 경기 구현은 그 경기 전술의 재현)에 따라 경기 값을 그대로 쓴다.','FotMob matchDetails 5739312 + SofaScore event 16285002; match_reports.id=2; core.kernel.Kernel(FC26).best_fit_slot(map25, regime_id=2, pos=ST)','MEDIUM 적합(단일 경기 실측 커널) / ⚠️⚠️ **표본이 32분 · hit_points 16**으로 유효 하한(45분+·hp15+) 중 분 조건을 못 채운다 — 에스테방(11분)과 같은 부류로 참고값이다. ⚠️ 단일 경기 프리셋이며 시즌 정본(prescriptions·team_tactic_setups)을 덮지 않는다. ⚠️ 이 경기 포메이션이 백3인데 슬롯 정본은 백4 기하다 — 슬롯 x가 완전히 대응하지 않는다. ⚠️⭐ **이 행은 2026-09-01 team_code 정리로 비로소 드러난 결손이다** — 잭슨의 이 출전이 `AVL`로 잘못 태깅돼 있어 G12의 조인(pm.team_code=mr.team_code)에 걸리지 않았고, 그래서 5개월간 누락이 은폐돼 있었다.',NULL,58);
